files.content:
*,
*::after,
*::before {
  box-sizing: border-box;
}

body {
  min-block-size: 360px;
  margin: 0;
  padding: 2em;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #fff;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

.title {
  margin: 0;
  margin-block-end: 20px;
  font-weight: 800;
  font-size: 38px;
  text-transform: uppercase;
}

fieldset {
  display: block;
  margin: 0;
  border: none;
  padding: 0;
}

.visually-hidden {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  margin: -1px;
  border: 0;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
}

label {
  display: block;
  font-weight: 800;
  font-size: 12px;
  text-transform: uppercase;
}

canvas {
  display: block;
  margin-block-end: 40px;
}

.widget {
  inline-size: 100%;
  margin: auto;
}

.controller {
  margin-block-end: 20px;
}

.settings {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
}

.settings fieldset {
  display: flex;
  align-items: center;
  gap: 10px;
}

.clear {
  max-block-size: 30px;
  border: 1px solid #000;
  padding-inline: 10px;
  padding-block: 5px;
  color: #000;
  font-family: inherit;
  font-weight: 800;
  font-size: 12px;
  text-transform: uppercase;
  background-color: #fff;
}

.clear:hover {
  box-shadow: inset 0 0 0 100px rgb(0 0 0 / 0.15);
  cursor: pointer;
}

.clear:focus {
  outline: 2px solid #000;
  outline-offset: 0;
}

.size-button {
  display: flex;
  justify-content: center;
  align-items: center;
  inline-size: 30px;
  block-size: 30px;
  border: 1px solid #000;
  padding: 5px;
  background-color: #fff;
  cursor: pointer;
}

.size-button:hover {
  box-shadow: inset 0 0 0 100px rgb(0 0 0 / 0.15);
  cursor: pointer;
}

.brush-size input:checked + .size-button {
  color: #fff;
  background-color: #000;
  pointer-events: none;
}

.brush-size input:focus-visible + .size-button {
  outline: 2px solid #000;
  outline-offset: 0;
}

.color-button {
  display: flex;
  justify-content: center;
  align-items: center;
  max-block-size: 30px;
  border: 1px solid #000;
  padding: 5px;
  background-color: #f00;
  cursor: pointer;
}

.color-button:hover {
  box-shadow: inset 0 0 0 100px rgb(0 0 0 / 0.15);
  cursor: pointer;
}
@media (pointer: coarse) {
  .size-button {
    inline-size: 50px;
    block-size: 50px;
    padding: 20px;
    font-size: 1.5em;
  }
  .color-button {
    max-block-size: 50px;
    padding: 20px;
    font-size: 1.5em;
  }
  .clear {
    padding-inline: 40px;
    padding-block: 10px;
    max-block-size: 60px;
    font-size: 1.5em;
  }
}
